quests[48283] = { id = 48283, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Standing Accused", description = "So you wish to speak with the accused?  I see no reason why not.\n\nBe quick about it, though. I will not have our trial delayed. This woman will answer for the fate of our village!", progress = "What is your business here, mainlander?", completion = "So Lady Waycrest has asked that you convince me to let her stand trial?\n\nI think she underestimates the danger of this situation...", objectives = "Speak with Lucy Waycrest in Hangman's Point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
