quests[48363] = { id = 48363, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Work Order: Florid Malachite", progress = "Are you here to deliver supplies?", completion = "Thank you for assisting us, jewelcrafter. We needed these florid malachites badly." }
quests[48364] = { id = 48364, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Work Order: Hesselian", progress = "Are you here to deliver supplies?", completion = "Thank you for assisting us, jewelcrafter. We needed this hesselian badly." }
quests[48365] = { id = 48365, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Young Lord Stormsong", description = "When the town fell, I got separated from my charge.\n\nLord Stormsong is being held hostage in his own house. I should've been there to protect him.\n\nWhen you go in there, succeed where I failed. Bring him back safely.", completion = "<Alby clears his throat.>\n\nIt is good to see the young lord safe.\n\n...Thanks.", objectives = "Kill Brother Conway, then rescue Lord Brannon Stormsong from Anglepoint Packing District.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48366] = { id = 48366, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paddle to Safety", description = "Perhaps... perhaps I can still help my people.\n\nI overheard conversations between the foreman and his men. It sounds as if the source of this corruption comes from the deeper waters, where the Stormriggers do their monster hunting.\n\nPlease, assist me in investigating this. I can still redeem myself and this operation.", progress = "I can't sit idly by anymore.", completion = "From here, we can launch our investigation.", objectives = "Use the Escape Rowboat to travel to Outrigger Post.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48367] = { id = 48367, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Those Aren't Fish Eggs", description = "Corruption has seeped into the sea.\n\nPart of our job is to keep the monsters of these parts under control. A cruel magic has taken over many of the beasts. I take the challenge of the hunt with pride, but too many and we are overrun!\n\nMonster eggs are scattered across the breeding grounds, pulsing with a dark energy.\n\nGet your stompin' boots on.", progress = "Ah, the satisfying squish of a monster egg under your boot. What a feeling!", completion = "It's best to not know what corrupted eggs will hatch into, though I could imagine the fight that we may now never see.", objectives = "Break 30 Corrupted Eggs in Krakenbane Cove.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48368] = { id = 48368, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deep Sea Defilement", description = "The sea...\n\nI understand its screams now. It is as if a veil has been lifted, revealing the chaos that has taken hold.\n\nCorrupting such a vast swath of sea cannot be done with simple spells. The cultists must have erected some sort of structures to channel their dark magics through...\n\nYou must find and destroy them, {name}. Only then can we hope to restore the waters to balance.", progress = "My mind is bursting with the tide's cries. It is almost too much to bear.", completion = "The screams have subsided, if ever slightly.", objectives = "Destroy the three Corrupting Pylons in the underwater caves in Krakenbane Cove.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48369] = { id = 48369, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Emergent Strategy", description = "My son went where? Chasing our workers into the woods once again?\n\nThat boy is too soft-hearted. No matter what I do, he will never be strong enough to take over the family business.\n\nI demand he come back this instant. He's got better ways to spend his time than going on wild goose chases for our employees!", completion = "Father is blinded in his pursuit of success. If he won't listen to our employees, I must!", objectives = "Find Benjamin Algerson near Fernwood Ridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48370] = { id = 48370, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Death in the Depths", description = "My own people have fallen to the mad whispers of the voices of the deep, deep sea.\n\nCultists inhabit caves in the ocean, spreading hysteria deeper and deeper into Tiragarde with their mad rituals.\n\nWe must put an end to them, {name}, before they get even more out of hand.", completion = "Perhaps now the danger may come to an end.", objectives = "Kill 8 Deepwarden Followers in Krakenbane Cove.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48371] = { id = 48371, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[48372] = { id = 48372, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eldritch Invocations", description = "This is my fault, my friend.\n\nThe leader of these cultists is none other than Director Deepwarden, a man who I once trusted as an advisor and business partner.\n\nIt seems he did not approve of how I ran our operation... to a ludicrous degree.\n\nHe gave his humanity for power, using his frustration to overthrow the village from the inside. Who knows what he plans next.\n\nI can no longer stand idly by. Take out Deepwarden. Show him that Anglepoint will not fall to his madness.", completion = "Is this truly the end?", objectives = "Kill Director Deepwarden in Krakenbane Cove.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48373] = { id = 48373, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Work Order: Lightweave Cloth", progress = "Are you here to deliver supplies?", completion = "Thank you for assisting us, tailor. We needed this lightweave cloth badly." }
quests[48374] = { id = 48374, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Supplies Needed: Lightweave Cloth", progress = "Are you here to deliver supplies?", completion = "Thank you for assisting us, {class}. We needed this lightweave cloth badly." }
quests[48375] = { id = 48375, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Primal Obliterum", progress = "Oh ho, whatcha got there? Primal Sargerite? Sounds fancy!\n\nI bet if we mash some 'o that stuff with Obliterum, we can make it beefier! Give it more of a punch when you apply it to yer armor.\n\nWhaddya say, want ta give it a try?", completion = "<As Caelen takes the Sargerite, you see him fusing it with the Obliterum near the forge. The power radiating from it is quite impressive.>\n\nHere you are, lad. Say, ya don't think this stuff is toxic, right?" }
quests[48376] = { id = 48376, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mass Primal Obliterum", progress = "Oh ho, whatcha got there? Primal Sargerite? Sounds fancy!\n\nI bet if we mash some 'o that stuff with Obliterum, we can make it beefier! Give it more of a punch when you apply it to yer armor.\n\nHeck, I bet if we smash a bunch of it together at once, we can make a whole batch 'o the stuff! Whaddya say, wanna give it a try?", completion = "<As Caelen takes the stack of Sargerite, you see him fusing it with the stack of Obliterum near the forge. The power radiating from it is quite impressive.>\n\nHere you are, lad. Say, ya don't think this stuff is toxic, right?" }
