quests[48393] = { id = 48393, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[48395] = { id = 48395, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Whispers from the Shadows", description = "Hero, we have a problem.\n\nThe ancient Necrodark cult has returned.\n\nWhen Dargrul was the Underking he would quell these cultists whenever they appeared, keeping them from exploring the vault of Neltharion.\n\nBut now, with Dargrul gone, they are sieging the vault in force.\n\nWe must stop them before they find what they are looking for.", objectives = "Help Navarrogg defeat the Necrodark.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48396] = { id = 48396, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[48399] = { id = 48399, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Dark (Iron) Tide", description = "Their red eyes... flaming beards... dark, dusky skin. These can only be Dark Iron dwarves. I have never seen one before this day.\n\nIt is my understanding that they have been sent here on an errand for the Alliance. Given my people's allegiance, I believe we are now placed in a position to better demonstrate our loyalty to the Horde.\n\nThe Dark Iron must die. See that they do not claim so much as an inch more of this beach.", completion = "Let there be no confusion on where we stand, {name}.", objectives = "Slay 7 Dark Iron dwarves.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48400] = { id = 48400, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grand Theft Telemancy", description = "They must not keep the Eye, {name}.\n\nFortunately I am more than an archaeologist. I am a telemancer. Chief Telemancer Oculeth himself trained the woman who trained my master. I can retrieve the relic with these arts.\n\nAll you need to do is place a telemancy beacon near the Eye. I can then retrieve both it AND you safely back to camp. The Alliance will find themselves empty-handed.\n\nWhile you're at it, do deliver my \"thanks\" to the individual responsible for snatching the Eye out from under us.", progress = "Did you find the source of the disruption?", completion = "Ahhh... it must be so disheartening to be at the mercy of such magics. Well done.", objectives = "Slay Urda Direflame and then place a telemancy beacon near the Eye of Xibala.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48402] = { id = 48402, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Poisonous Touch", description = "You... I saw you speak with Zentimo. Please, I don't have much time left...\n\nThese trolls, they came for our blood. I was already nearly bled dry before this one succumbed to my poison.\n\nSearch it's body, the blowgun and darts should still be there. Dip the darts into my blood and use them to weaken as many of their number as you can. \n\nI will not let my death be in vain! If these trolls want our blood so badly, then they shall have it!", completion = "I see, You've brought meaning to Mag'ash's sacrifice.\n\nThank you for your valor, {name}.\n\nPlease, take the weapon with you and go with my blessing.", objectives = "Use the blowgun to weaken 5 Bloodhunter trolls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48403] = { id = 48403, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Darkness", description = "For thousands of years, the Darkness was held at bay. The wards stood... protecting Highmountain.\n\nNow they are gone, and evil is free once more.\n\nThe Darkness that haunted our dreams... that even the kobolds spoke of only in frightened whispers... has come.\n\nUul'gyneth, herald of the Old Gods, paves the way for his masters. Unless we stand together and defeat him, all is lost.\n\nYou must hold nothing back, champion. None of us can.", completion = "I cannot put into words how much you have done for us this day, or how grateful I am to have you as an ally.\n\nYou have our thanks, hero. You have MY thanks.\n\nI owe you a great debt for this.", objectives = "Defeat Uul'gyneth the Darkness.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48404] = { id = 48404, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Scamps", description = "You there! You have legs and a need for money? I wish to hire you.\n\nConfounded, despicable, parentless children have been stealing my scrolls again. Those scrolls are dangerous in the wrong hands.\n\nWhat is worse, I believe these junior vagabonds to be organized.\n\nFind these street scamps and relieve them of their bounty, and I shall pay you for it.", progress = "The little rascals are crawling all over these accursed docks.", completion = "It pains me to pay you for something I could have done myself when I was younger, but these legs do not move as swiftly as they once did.", objectives = "Stop 5 Street Scamps from stealing.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48405] = { id = 48405, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mista Nice", description = "I am normally not a violent tortollan, but if there is one thing I cannot abide, it is a scoundrel using children for his own profit.\n\nThe street scamps appear to be working at the behest of a ring leader. I do believe they call him \"Mista Nice\" though I suspect the name to be sarcastic in nature.\n\nI have a scroll here that can let you move among the scamps and see if they lead you back to Mista Nice. If they do, slay him and I shall pay you a bounty.", progress = "Any luck finding that voice of corruption for the youth of tomorrow?", completion = "Excellent. One less evil troll on the streets. Of course, you can assume they will organize again soon. They always do.", objectives = "Find and slay Mista Nice.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48419] = { id = 48419, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lured and Allured", description = "Lookin' for a friend from the wreck, eh?\n\nIf he survived he may have wandered up the path to our camp.\n\nNow if he ain't up there toastin' his buns by the fire, well... lotta poor souls fall victim to the song of the sirens. \n\nYou should check the camp before you go wadin' out into the tideway. Ask our leader, Stabby Jane. She'd know for sure if a new survivor showed up!", completion = "Ugh... Was I... Was I crying?\n\nLet's agree to never speak of this again.", objectives = "Search for Flynn Fairwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48420] = { id = 48420, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[48421] = { id = 48421, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood in the Tides", description = "Curse these slimy wenches!\n\nTheir singin' sets men's hearts afire and their brains adrift. \n\nMy ship's aground. My cargo's lost.\n\nNothin' for it now but to fight!", completion = "<Keelson looks up at you from a pile of siren corpses.>\n\nI need a drink.", objectives = "Slay 8 Wailing Sirens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
