quests[48431] = { id = 48431, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[48433] = { id = 48433, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Together We Are the Horde!", description = "What began with a simple feast led to a battle against an ancient evil seeking to consume the world.\n\nMy kind of day!\n\nYour deeds have helped secure an alliance between Orgrimmar and Highmountain. These tauren will make a valuable addition to the Horde.\n\nThe Warchief will be pleased.", completion = "It seems we have secured a new ally. You have done well.\n\nThe Highmountain tauren are famed for their prowess in battle. I look forward to the pummeling they will unleash upon the Alliance.", objectives = "Speak with Ji Firepaw at the Orgrimmar Embassy to hear the end of this tale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48434] = { id = 48434, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "How Fares Ebonhorn?", description = "Three of the ancient wards are restored. The mountain is not yet secure, but we may have done enough to break Ebonhorn free of the shadows gripping him.\n\nLet us return to Thunder Totem and see how he fares. Hopefully Ebonhorn can tell us more about what is happening with the Necrodark and the insidious master they serve.", completion = "I am myself again, {name}.\n\nYou and Graysky have freed me from the grasp of the Old Gods. Had I remained in that state for much longer, I would have been lost.", objectives = "Return to Thunder Totem and check on Ebonhorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48435] = { id = 48435, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Spiritwalkers", description = "Ebonhorn is in the care of Spiritwalker Graysky. A cure is proving elusive... he has asked for your help.\n\nPlease speak with him at once, {name}. The spiritwalkers are the keepers of our past. I pray the answer lies somewhere in the ancient truths they hold.", sourceObjective = "Speak with Spiritwalker Graysky at Thunder Totem in Highmountain.", sourceObjectiveStatus = "unverified-source-field" }
quests[48440] = { id = 48440, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Night", description = "What we do this day, we do for Azeroth. For the countless souls lost to the Legion's foul crusade.\n\nOnce you are ready we will take the Vindicaar into the very heart of the Legion.\n\nArgus awaits.", completion = "We must act quickly!", objectives = "Travel to Argus aboard the Vindicaar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48441] = { id = 48441, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Remnants of Darkfall Ridge", description = "My riders have talbuk, but my people need supplies. Food. Tools. Weapons.\n\nFor millennia, we have migrated from one hovel to the next, moving each time the Legion discovered us. Never able to flee with our possessions, we left them behind.\n\nYou are powerful, your followers are capable, but you do not know Argus. The landscape will dispatch you as mercilessly as the Legion. Recover our supplies from Darkfall Ridge, and I will order my people to guide your forces through the Argus Wastes.", completion = "You have recovered our supplies. As promised, we will aid your forces on Argus.", objectives = "Use the Scouting Map and complete the mission, \"Darkfall Ridge Supplies\".", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48442] = { id = 48442, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nath'raxas Hold: Preparations", description = "One of two fates await krokul prisoners taken to Nath'raxas Hold. Consume the fel, and become a willing soldier in the infinite army, or be mutated into a disfigured abomination. An ur'zul.\n\nWhile the Army of the Light occupies the Legion's attention, I am presented with an opportunity to save my people. I ask for your aid.\n\nBefore we begin, your forces must be adequately equipped.", completion = "Soon, the krokul will raid Nath'raxas Hold. My people are anxious to begin.", objectives = "Raise 6 Champions to 900 Item Level.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48443] = { id = 48443, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nath'raxas Hold: Rescue Mission", description = "Your forces are adequately equipped for the mission to save my people from Nath'raxas. Order your champions to bolster my assault, and together we will dismantle the Legion's stranglehold over the region.", completion = "We were a great civilization, once. But, now?... Thank you, {name}. Our combined forces freed many from Nath'raxas. With fewer slaves, and the Army of the Light on their doorstep, the Legion's influence over this region will be greatly diminished.", objectives = "Use the Scouting Map and complete the mission, \"Nath'raxas Breakout\".", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48445] = { id = 48445, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ruins of Oronaar", description = "Many krokul wander the city below, shrouded in shadow. I will not accept that they are all beyond redemption.\n\nArkhaan was a leader, once. Some among his followers may still reside in the ruins of Oronaar, straddling the thin divide between reason and oblivion. Enlist the aid of your order. Scour the ruins for any that can be saved.", completion = "Your champions discovered someone living in a cave beneath Oranaar. He is hiding from the Void-Touched, and he appears lucid.", objectives = "Use the Scouting Map and complete the mission, \"Inches from Madness.\"", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48446] = { id = 48446, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Relics of the Ancient Eredar", description = "I failed Arkhaan. I won't fail again. \n\nIf there is to be any hope of freeing the krokul, the ethereal threat must be removed from Eredath. L'ura has been vanquished, but the void clings heavily near the Shadowguard Incursion.\n\nBefore we commence, ensure your forces are protected from the shadow. Your champions should seek ancient eredar armaments in the nearby ruins.", completion = "The voidcallers roaming the Shadowguard Incursion must be extinguished. Your people are sufficiently armed for the coming encounter.", objectives = "Raise 6 Champions to 925 Item Level.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48447] = { id = 48447, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadowguard Dispersion", description = "Lend me the aid of your order once again, that we might end the Shadowguard threat permanently. While you confront the Legion, we will face the void. The attack commences once your forces arrive.", completion = "With L'ura defeated, and the voidcallers eliminated, the Shadowguard's dominance over the city has been crippled. if our campaign against the Legion is successful, there could be a future for the creatures living here.", objectives = "Use the Scouting Map and complete the mission, \"Shadowguard Dispersion\".", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48448] = { id = 48448, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hindering the Legion War Machine", description = "{class}t, I could use your help. The Army of the Light is coordinating an attack against the Spirit Crucible, Terminus, and Shaper's Rise to cripple the Legion's ability to wage war outside of the Antoran Wastes. We do not have enough soldiers to defend our footholds and execute this operation.\n\nWill you approach the {class}s on our behalf? This gambit could succeed with them fighting by our side. We can paralyze the Legion war machine.", completion = "Three Legion facilities decimated in a single operation. Extraordinary.", objectives = "Use the Scouting Map and complete the mission, \"Gambit in the Wastes.\"", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48449] = { id = 48449, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[48450] = { id = 48450, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[48451] = { id = 48451, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[48452] = { id = 48452, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Red Market", description = "You came with de Princess Talanji?\n\nI need a hand with a most unsavory task. Crimson cultists have made demselves a market for blood magic. Dis is bad, mon. Dis is very bad indeed.\n\nI need you to go down dese steps and bring back any evidence you can of blood practices. And destroy their chalice. Big chalice. Don't forget de chalice.", progress = "In Zuldazar, such magic is forbidden for a reason. Dey say you give in to dis magic, you hear voices. And sacrificing, well, dat is de practice of de lower tribes.", completion = "Blood magic is an infection. It spreads like a disease if not purged.", objectives = "Collect 3 Dark Fetishes and destroy the Chalice of Calling.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48453] = { id = 48453, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strike Back", description = "As you may have seen, the ritualists in this forest kidnap our people and perform heinous rituals on them. The souls of our fallen now roam as twisted creatures. This sin cannot go unpunished. Kill as many ritualists as you are able, but be sure to strike at the dark demon that leads them.", completion = "You've been a great asset to my wranglers here. Please take this as a token of our gratitude.", objectives = "Kill 8 Eredar ritualists and Lady Shahrazad in the Petrified Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48454] = { id = 48454, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Evidence of Evil", description = "Jakra'zet refused to patrol dis area. Yazma's spies did not warn us of de evil lurking beneath our city. And Zul did not foresee blood magics festering under our noses.\n\nThese are serious allegations, and de evidence is in your hands. Present dem to Zolani, Blade of the King. She will know best their meaning and how best to present dem to de king.", completion = "Blood magic being practiced in open daylight? Dis cannot stand.\n\nYou have done well in bringing me dis information. I will present it to King Rastakhan at de first opportunity when his council is away.", objectives = "Speak with Zolani, Blade of the King.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48455] = { id = 48455, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Duskcloak Problem", description = "Here in this forest, species of talbuk and panthara still roam. However, the balance has been disrupted and now the panthara risk hunting the talbuk to extinction. To ensure their survival, we must decrease the number of panthara.\n\nDo not let their suffering linger. A swift death is the most merciful.", completion = "Keeping balance within the forest ensures its longevity.", objectives = "Kill 10 panthara within the Petrified Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48456] = { id = 48456, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Witch Doctor Jala", completion = "Greetings, {class}. I am Witch Doctor Jala. And you are right on time.", objectives = "Find Witch Doctor Jala.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48457] = { id = 48457, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[48460] = { id = 48460, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wranglers", description = "Great evil exists on Argus and our forests house some of the worst of it. My wranglers are at the edge of the forest and are waiting for reinforcements. That would be you.\n\nSeek out Lead Rider Jerek, he will tell you more.", completion = "I fear the forest may be lost.", objectives = "Speak to Lead Rider Jerek in the Petrified Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48461] = { id = 48461, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where They Least Expect It", description = "The Legion's fanatical crusade leaves them spread thin. As they focus their defenses on Argus, we are free to tear into their forces on other worlds.\n\nTravel through an Invasion Point on Argus and show the Legion that there is no hiding from death.", progress = "No demon is safe while I draw breath.", completion = "So many Legion worlds are ripe for the taking...", objectives = "Enter an Invasion Point and defeat a Legion Commander.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48465] = { id = 48465, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vrax'thul" }
quests[48466] = { id = 48466, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ven'orn" }
quests[48467] = { id = 48467, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Puscilla" }
quests[48468] = { id = 48468, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bwonsamdi's Deliverance", description = "We be havin' a task from Bwonsamdi, da loa a death, ta purge dis place of its undead.\n\nDey be controlled by a monster called Kel'vax.\n\nCan ya help? Dere be zombies destroyin' Bwonsamdi's temple over dere, and we no have da strength ta fight 'em all.\n\nTake dis torch. Kill dem zombies, den burn them corpses with da torch. It should be deliverin' their souls ta Bwonsamdi.\n\nYa do dat, and we be one step closer ta stoppin Kel'vax.", completion = "Ya did good, I can tell Bwonsamdi be pleased by ya releasin' his followers.", objectives = "Burn 10 defiled troll corpses with the cremation torch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48473] = { id = 48473, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Respecting the Rites", description = "If we be deliverin' Kel'vax's soul ta Bwonsamdi, we need ta be doin' it properly. We need ta be doin' two things.\n\nFirst, dere be torches remainin' around da temple nearby. Light dem with da torch I gave ya.\n\nDa torches used ta be our way ta show dat we be deliverin' a spirit ta Bwonsamdi. Kel'vax will be knowin' it be his time.\n\nSecond, I be needin' special ritual powder dat be deep within da temple. It be da key ta stoppin' Kel'vax.\n\nGo now, I be prayin' Bwonsamdi be favorin' us.", progress = "Light dem torches and get da powder so we be gettin' Bwonsamdi's favor.", completion = "Good! Did ya feel Bwonsamdi's presence, even if it just be for a second?", objectives = "Light 5 Ritual Torches and recover Shinga Deathwalker's Ritual Powder.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48474] = { id = 48474, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crypt Keepers" }
quests[48475] = { id = 48475, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeing Spirits", description = "The spirits in the cemetery are riled up! I'd ask 'em direct but I don't have any of the necessary salve I use to commune with the dead. My family's been making it for ages!\n\nThe herbs and tools I use to make it are inside, but I can't get over there! Some of those spirits are beyond reason and attack me on sight!\n\nWhy don't you go collect those herbs, make the salve with my tools, and ask one of the calmer spirits what's going on. Aaron Cresterly is a good spirit to look for.", progress = "Stranger, lend me your aid! I am ensnared in a witch's foul magic and I do not know how much longer I can resist! Destroy the circle binding me!", completion = "A witch has infested this goodly place with her foul power. Stranger, you have proven yourself a friend. Perhaps you will be our salvation!", objectives = "Collect Gravebloom, create and use salve, then find Aaron Cresterly.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48476] = { id = 48476, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Split Party", description = "In life my compatriots and I were valiant champions as you are. In death we are potent souls to make the witch's accursed minions even more powerful. \n\nWith your help I have resisted thus far, but this foul witch pulled brave Bridget from her justly won rest. She is now trapped in one of these macabre constructs. This witch intends to use Bridget to bring death upon the lands she was oathsworn to protect!\n\nFree Bridget Fairwater's soul from the construct which entraps her!", completion = "Why that pustulent boil on a toad's rump! Use me as a pawn? Fie! I will see her sent screaming to the foul pit she crawled from!\n\nMy thanks. The witch will pay for her heinous actions!", objectives = "Free Bridget Fairwater's soul.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48477] = { id = 48477, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Looking For One More", description = "Our loathsome foe, 'Sister' Westwood, yet continues her work. After subjugating myself, she set her malicious sights on my companion, fair Mercy. \n\nOf us three, Mercy was most kind and possessing of uncommon inner strength, yet I fear for her. Corrupting such a soul would make for a fearsome creature, indeed.\n\nStop the vile ritual before Mercy is taken. Allow the dead their rest. Slay Sister Westwood and free us from her grasp!", completion = "Our thanks to you, brave champion. You have freed us from the witch's vile influence and stopped her corruption from spreading. Our very souls have been saved by thy actions.\n\nNow we may rest.", objectives = "Slay Sister Westwood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48478] = { id = 48478, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kel'vax's Home", description = "Kel'vax's soul be bound ta three phylacteries, protected by his voodoo. Even if ya destroy him, he just be reformin' in dem.\n\nMe old power be returnin' after ya lit dem torches. I be able ta enchant dis powder dat allow ya ta go through Kel'vax's voodoo.\n\nFind dese phylacteries and bring 'em ta me. We gonna look Kel'vax in da eye when we destroy 'em.\n\nI should warn ya... dis powder might be messin' with ya head. Ya may have some... visions after ya use it. Be careful.", progress = "We need dem phylacteries if we be havin' a chance ta destroy Kel'vax.", completion = "Good! I be savin' dis for later. I want to be lookin' Kel'vax in da eye when we be destroyin' his phylacteries.", objectives = "Use Shinga Deathwalker's Spirit Powder to take Kel'vax's Ancient, Repaired, and Pristine Phylacteries.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48479] = { id = 48479, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bones for Protection", description = "Kel'vax be havin' powerful voodoo on his side, da kind dat could kill ya instantly if ya not careful.\n\nI know how we can be stoppin' dis magic, but we need bones. Lots a them. We be lucky, Kel'vax be havin' a large skeleton army.\n\nI need ya ta be goin' out dere and collectin' their bones. Bring 'em ta me and I'll prepare 'em ta be used against his voodoo.", progress = "Did ya get them bones? We need 'em if we gonna stop Kel'vax's voodoo.", completion = "Good! I be workin' on usin' dese bones to counter Kel'vax's dark voodoo.", objectives = "Collect 40 Cursed Bones.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48480] = { id = 48480, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fall of Kel'vax", description = "We be ready ta kill Kel'vax and send his soul ta Bwonsamdi for judgment. Ya should know someting before ya go in.\n\nKel'vax was our son. Dat be why Bwonsamdi chose us ta stop dis madness.\n\nI not be knowin' why Kel'vax chose ta forsake everyting we believed in centuries ago... but here we are.\n\nEven without his undead, Kel'vax be very powerful. Be prepared... dis be our shot to end him and find our rest.", progress = "Ya must destroy Kel'vax once and for all!", completion = "It be over. As ya can see, Kel'vax be trapped in his phylacteries.\n\nAll dat's left for us ta do is ta destroy da containers ta send him ta Bwonsamdi for judgment.\n\nWe couldn't have done this without ya. May Bwonsamdi be wit ya... and may ya be wise enough ta know when ta make a deal with him.", objectives = "Defeat Kel'vax Deathwalker.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48483] = { id = 48483, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Stranger's Plea", description = "My people... enslaved...\n\nBeaten... within death's grasp...\n\n<The cowled figure weakly raises his arm, handing you a small liquid skin.>\n\nHelp... us...", completion = "A cowled figure... and it did not attack you?\n\nMost curious.", objectives = "Heal 8 Felbound Drudges.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48489] = { id = 48489, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Spires of Home", description = "My sister Vereesa told me of the events that led to the high... excuse me, \"blood\" elves joining the Horde.\n\nPart of me still can't accept it.\n\nPrince Kael'thas led my people down a dark path. I have to believe the majority of sin'dorei would shrug off the Horde if given the choice.\n\nThe last time I spoke to Lor'themar, we served together in the Farstriders. He was a fine ranger and a good man. I pray the years have not changed that.\n\nCome. We must not keep the regent waiting.", sourceObjective = "Meet Alleria Windrunner on the Isle of Quel'Danas.", sourceObjectiveStatus = "unverified-source-field" }
quests[48492] = { id = 48492, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Getting a Leg Up", description = "I seem to be in a bit of a... predicament.\n\nMy squad was scouting on behalf of Lady Sylvanas when we were ambushed by some snake men calling themselves \"sethrak\".\n\nAs you can see, my legs have been separated from my body in the ambush. It's just a flesh wound, luckily.\n\nCare to help me get re-attached? Then we can get down to this business of vengeance against these sethrak.", completion = "That feels a lot better, I think. Time to get down to the business of some proper revenge.", objectives = "Recover Chadwick Paxton's legs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48496] = { id = 48496, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reuniting the Company", description = "Right, then. First order of business, rescue the remnants of my company. \n\nThese sethrak kept yelling about expanding their empire and conquering Azeroth as they attacked us. Lovely, really.\n\nThey killed most of my company and took some hostages. I assume they're being told how grand the sethrak empire is.\n\nI'd like the remnants of my company back, if you please. I'll put in a good word with Lady Sylvanas, once this is all over. \n\n...not that someone like you needs it.", completion = "Fine work! It's good to be reunited, both with my body and with my squad.", objectives = "Rescue the remnants of Chadwick Paxton's squad.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48497] = { id = 48497, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Show of Force", description = "These things called the sethrak think that we're easily handled. That's only because we were ambushed and not ready for a fight.\n\nWell, all right, perhaps we were easily handled. But that doesn't mean we won't strike back.\n\nKill as many of those sethrak as you can. I don't know who they are or what they want, but I do know one thing.\n\nThey signed their death warrants when they attacked my squad and cut me in half.", completion = "Good! I could hear their screams from here. They will remember the Horde!", objectives = "Defeat 10 Sethrak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48498] = { id = 48498, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Mercy for Sithis", description = "Heh heh... thanks for the rescue! I could use your help in a little plan that I have.\n\nThe commander of this place is a sethrak called Sithis. He's got this thing called a \"skycaller gem.\"\n\nWord is they're looking for some sort of shadow magic in Nazmir to try and really power this thing up.\n\nHeh heh... luckily, yours truly has her own shadow magic to do just that! Maybe you do, too. I don't keep up on what powers you keep getting.\n\nGet the gem from Sithis and we'll have some REAL fun afterwards.", progress = "Do you have Ingrid's gem? Please tell me you do... she's been absolutely insufferable about it.", completion = "Excellent work freeing Ingrid. She has told me about this particular gem, and the company has voted that you should test it out on our snake enemies.", objectives = "Recover the Skycaller Gem from Fangcaller Sithis.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48499] = { id = 48499, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Dust", description = "It appears the sethrak are quite serious about keeping this gem. I do wonder where they found it in the first place.\n\nHrm... perhaps Lady Sylvanas would be interested in this as well. Something to ponder.\n\nIngrid believes this gem can unleash lightning and shadow magic of, her words not mine, epic proportions.\n\nI do believe it would be best for everyone if you tested it out on the small sethrak army currently looking for us.", progress = "Would you please hurry and deal with the sethrak? I'd prefer to get everyone's bloodlust dealt with before heading out.", completion = "Good work. The sethrak will be back, but we've proven our point, which is don't cross the Horde.\n\nWith that business over with, my squad will be off. Hopefully the next time we meet will be under... nicer circumstances.", objectives = "Defeat 20 Enraged Sethrak with the Skycaller Gem.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48500] = { id = 48500, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Moment of Respite", description = "For all we have seen, we must remember not to dwell on the past, but to look forward and prepare for what is to come.\n\nTake this opportunity to familiarize yourself with the Vindicaar.", progress = "Light guide your path.", completion = "Are you ready to continue on our journey?", objectives = "Speak with Artificer Shela'na, Thelbus Wimblenod and High Priestess Ishanah.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48502] = { id = 48502, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Naroua, King of the Forest" }
quests[48504] = { id = 48504, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Through the Old Roads", description = "Lady Waycrest has entrusted me with securing the town of Falconhurst and the services of Master Alchemist Ashton who lives there. However, I have found out no one has heard from Falconhurst in some time.\n\nThe skies above the forest are impassable, so we must travel the old roads through Drust ruins in the mountains. A small capable party has a better chance to bypass the growing forces of the witches and to help secure Master Alchemist Ashton.\n\nTo that end, I ask you to assist me.", completion = "Something has disturbed the spirits here.\n\nThe spirits of the departed still fight with constructs and the shambling dead. \n\nOur goal is Falconhurst, but a quick investigation of this area might help us fight our foes better.", objectives = "Meet with Inquisitor Cleardawn at Gol Osigr.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48505] = { id = 48505, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lovesick and Lost", description = "Ugh. My head. My HEART.\n\nFeels like a good hangover and a bad breakup put together.\n\nOn the bright side, I think I know where we are. And where that ship was headed.\n\nFreehold.\n\nIt's a... free town. For, uh... free folk. The only rule is that there are no rules. Lotta guys with peg legs and eye patches and exotic pets. Catch my drift?\n\nThere's a trail through the hills that'll take us there. Pretty sure I remember the way...\n\nLet's get moving. Gotta walk off that damn siren's witchery.", completion = "Told you I knew how to find it!", objectives = "Escort Flynn to Freehold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48506] = { id = 48506, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hand of Fate", description = "Ever since the Legion invaded the Exodar, the draenei have been hard at work preparing to return to Argus. At long last they have a vessel that can take us there.\n\nWith the way to that dreadful world open, we simply could not ask for a better opportunity to strike. Prophet Velen called for you quite specifically to join the assault force.\n\nYou should make your way to Stormwind Harbor right away. Arrangements have been made for a ship there to take you to Azuremyst.", completion = "I'm glad you were among those called for the expedition to Argus. There will be plenty of fighting ahead.", objectives = "Meet your escort to the Exodar at Stormwind Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48507] = { id = 48507, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hand of Fate", description = "Ever since the Legion invaded the Exodar, the draenei have been hard at work preparing to return to Argus. At long last they have a vessel that can take us there.\n\nWith the way to that dreadful world open, we simply could not ask for a better opportunity to strike. Prophet Velen called for you quite specifically to join the assault force.\n\nYou should make your way to Bladefist Bay right away. Arrangements have been made for a ship there to take you to Azuremyst.", progress = "It seems fate has conspired to bring us together, {name}.", completion = "I knew you would be among those called to fight. It will be an honor to fight by your side.", objectives = "Meet your escort to the Exodar at Bladefist Bay.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48509] = { id = 48509, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Commander Sathrenael" }
quests[48510] = { id = 48510, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Commander Vecaya" }
quests[48511] = { id = 48511, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Commander Endaxis" }
quests[48512] = { id = 48512, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sister Subversia" }
quests[48513] = { id = 48513, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invasion Point Offensive", description = "The invasion points are key to cutting off Legion reinforcements to Argus. Defeating their armies within the lesser portals will allow us to assault larger invasion points and extinguish the Legion presence within.", progress = "The offensive continues.", completion = "The Legion's defeat is at hand.", objectives = "Complete 3 Invasion Points.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48514] = { id = 48514, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slumbering Behemoths" }
quests[48515] = { id = 48515, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Silver Blades", description = "<This drust warrior was felled by a silvered blade long ago. This blade is still good despite the ages.\n\nPerhaps these weapons could be brought into service of fighting the Drust once more.>", objectives = "Collect 6 Tarnished Blades from the Fallen Defenders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48516] = { id = 48516, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Toxic Community", description = "A traveler? Nobody uses this trail unless they got a death wish.\n\nThe only thing more poisonous than the marrowflies are the saurolisks that eat 'em all day.\n\nThat marrowfly toxin is what I'm here for. Y'see, I'm a purveyor of, uh... specialty goods. And my clients are just dyin' for more of my product. Heh.\n\nYou bring me their stingers, I pay you. Simple as that. \n\nYou can even find 'em in the saurolisks, if you don't mind gettin' your hands dirty.", progress = "You got them stingers?", completion = "Pleasure doin' business with you.\n\nIn the future I'll make sure you get a special discount. Heh.", objectives = "Gather 50 Toxic Stingers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48517] = { id = 48517, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honorable Discharge", description = "Some of the spirits on the battlefield are too weary to go on. These were brave Kul Tirans. They have more than earned their rest but their sense of duty holds them here.\n\nOrder the most weary spirits off the field of battle. Hopefully they will be convinced to rest.", completion = "It is good their spirits returned to their final rest once more. May they never be disturbed again.", objectives = "Dismiss 10 Weary Spirits from the battlefield.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48518] = { id = 48518, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Save Who We Can", description = "These things seem intent on capturing our people... but we're not quite sure what for.\n\nThe ones in the town might be too tough to reach right now, but we might be able to save some of the woodsmen who work along the strand.\n\nHead to the lumber fields just east of here, and see if there's anyone still alive out there. We can shelter them here until we can arrange safe passage out of here.", completion = "Good work, {class}! Even if we don't manage to take the town back, it's good to know we were able to save some of our people.\n\nNow we just have to get them out of here...", objectives = "Rally 6 Frightened Woodsmen in the Timbered Strand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48519] = { id = 48519, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hope They Can't Swim", description = "We've got a small boat docked right across the way there. If we can get these villagers safely on board, they should be able to make it to Fallhaven by river.\n\nYou're a capable fighter, no doubt. Can I count on you to fend off any attackers while we get them to safety?", progress = "We can begin evacuating on your mark.", completion = "Thank you, {class}. Those villagers owe you their lives.\n\nNow that they're safe, we can focus on taking back the town.", objectives = "Defend the villagers as they board the boat in the Timbered Strand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48520] = { id = 48520, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Three Sisters", description = "If you're looking to absolve Miss Waycrest of this mess, you'll need to head into the town. Recently, I've seen some oddly dressed women among the creatures, who seem to be calling the shots.\n\nIt's likely that they're the key to this whole nightmare, but we can't get in to question them. Their minions don't seem to slow you down, though. \n\nIf you can get to them, you might be able to find some answers for the both of us.  Be careful, though. They likely aren't very friendly.", completion = "They weren't willing to talk?  That's unfortunate.\n\nAt least with them gone, we may stand a chance to take back the town.", objectives = "Confront Sister Ashwell, Sister Early, and Sister Mooring in Fletcher's Hollow.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48521] = { id = 48521, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Charming the Lifeless", description = "<You've seen a charm like this in Fallhaven being used to control a wicker construct.\n\nIf you can figure out how to use it, you may be able to take control of one of the coven's wicker constructs.>", progress = "What's this?", completion = "You were able to control one of their creations?! That's amazing!\n\nThis could really turn the tide for us!", objectives = "Test the Wicker Charm on Dormant Ravagers in Fletcher's Hollow until you successfully control one.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48522] = { id = 48522, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Revealing Missive", description = "<The strange woman possessed a letter from someone calling herself \"Matron Levae\" which appears to have orders to take the town of Fletcher's Hollow.\n\nThis could be the evidence needed to absolve Lucille Waycrest. Mayor Pare should be interested in seeing this.>", completion = "It would seem we were mistaken. Miss Waycrest was just in the wrong place at the wrong time.\n\nHowever, this also means that Fletcher's Hollow may be in even more danger.", objectives = "Return to Evelyn Pare.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48523] = { id = 48523, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Murderous Matron", description = "I know that you've got what you came for, but I need to ask you one more favor.  This town won't be safe until this Matron Levae is taken care of. \n\nAccording to the letter, she must be holed up in that cave. None of our people have been able to enter it, but I know I've seen their constructs go in!\n\nThis charm you found might be the key. If you can take control of one of these wicker men and send it after her, we might have a shot!", progress = "Is she gone?", completion = "It worked?! Well, I'll be a kraken's uncle! You really did save our hides!\n\nI'm not sure how we can repay you, but this should be a good start!", objectives = "Control the Dormant Ravager to defeat Matron Levae in the Elderstone Mine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48524] = { id = 48524, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Culling the Coven", description = "If the mine really was their objective, I can only imagine they'd have even more forces in there.  \n\nMy men and I may be able to take care of the remnants out here, but if an even bigger force comes out of that mine, we're not going to stand a chance.\n\nWhile you're hunting down the matron with this wicker contraption, do you think you could... you know... soften them up a bit?", completion = "Wait... you're telling me it was even worse in the mines?\n\nYou know what? Just don't tell me about it. So long as you killed... whatever was in there... I think we'll be okay.", objectives = "Kill 25 of Matron Levae's minions in the Elderstone Mine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48525] = { id = 48525, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Break Them to Splinters" }
quests[48526] = { id = 48526, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scuttled" }
quests[48527] = { id = 48527, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ravenous Landsharks", description = "Warbeast Kraal is important to de empire. All de beasts dat haul our goods, carry our armies, and fight our wars are born and bred here. \n\nIf you want Rastakhan's support, you had better impress us. I have some thoughts on where you can start.\n\nWe have ourselves a diemetradon problem. Usually nothing to worry about, but dey had a big hatching dis year. Now dey're breaking into de pens and eating our eggs.\n\nKill diemetradons, protect our beasts, and we will see about de rest.", progress = "Were you able to kill any diemetradon?", completion = "You are good at dis. Almost like you have done it before.", objectives = "Kill 9 Ravenous Diemetradon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48529] = { id = 48529, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hungry Mouths To Feed", description = "We don't have much in de way of supplies right now.\n\nMojambo and his gang will be back to finish us off, of dat I'm sure. But without food and supplies, dere will be none of us alive for dem to kill.\n\nOur cook is looking for someone to help gather supplies so we can feed de camp.\n\nSpeak with him and see if you can find what he's looking for.", completion = "A newcomer, eh? You picked a bad time to join our tribe. You'd find better luck wandering de wastes in search of mirages.", objectives = "Speak with Sezahjin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48530] = { id = 48530, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Heard You Lost the Herd", description = "Our herd of alpacas went missing dis morning.\n\nIt may seem like we have more pressing matters to worry about, but de meat and milk de alpacas provide are essential to our survival.\n\nThose alpacas won't survive long on de dunes. Speak with Mugjabu and help him find de alpacas before it's too late!", completion = "Razgaji sent you? I'm not sure why he cares so much. When Mojambo and his gang come back, we'll all be dead anyway...", objectives = "Speak with Mugjabu.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48531] = { id = 48531, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mystery Meat", description = "Mojambo's gang may be coming to kill us, but we've still got to eat. And when you live in a harsh wasteland, you make do with what you've got.\n\nSometimes fresh meat is hard to find.\n\nDat's how I came up with de idea for my famous mystery meat pie.\n\nDe secret ingredient is dung beetle, but with enough seasoning you can't even tell!\n\nOur food supplies are dangerously low right now. I need someone to go beetle hunting as soon as possible!", progress = "Do you have de \"mystery ingredient\" for de mystery meat pie?", completion = "Just look at all dese juicy intestines! We'll have enough pies to feed de entire camp!", objectives = "Collect 8 Dung Beetle Innards.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48532] = { id = 48532, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alpacas Gone Wild", description = "Our herd of alpacas escaped dis morning. Dey're out dere wandering de dunes as we speak.\n\nProbably for de best, if you ask me. We'll all be dead soon once Mojambo comes back.\n\nSince you seem to care so much, take dis alpaca whistle and use it to round dem up. I blow de whistle every day at feeding time, so de alpacas should come running home when dey hear de sound.", completion = "Looks like you recovered most of de herd. Good work... even though Mojambo and his henchmons will probably murder us in our sleep and take de alpacas for demselves...", objectives = "Round up 6 Alpacas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48533] = { id = 48533, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vol'duni Fried Chicken", description = "Have you ever tried my delicious Vol'duni fried chicken?\n\nMe neither! Probably because dere aren't any chickens in Vol'dun.\n\nDere are plenty of vultures, though. Why don't you see if you can find some tasty vulture meat?\n\nDe secret to delicious fried chicken is to roast de meat before you fry it, but it only works if de meat is fresh.\n\nI've soaked dese arrows in alpaca fat. If you ignite de arrows and shoot down de birds, dey'll start cooking before dey're even dead!", progress = "Do you have de buzzard meat?", completion = "It may not be chicken, but it's food! With enough seasoning nobody will know de difference.\n\nEverything tastes like chicken, right?", objectives = "Collect 8 Roasted Buzzard.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48534] = { id = 48534, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Snarltooth's Last Laugh", description = "It's not just Mojambo's gang we have to worry about. We also need to keep a watchful eye at night due to frequent hyena attacks.\n\nDe most dangerous of de hyenas is Snarltooth. He ambushes us at night, laughing maniacally as he slaughters his prey.\n\nI need you to slay de beast once and for all! Snarltooth's den is just south of de arena in de Arid Basin.", progress = "Did you take care of Snarltooth?", completion = "It's good to finally see dat hyena got what he deserved! If you're strong enough to slay Snarltooth, maybe we stand a chance against Mojambo's gang...\n\nWho am I kidding, we're dead meat.", objectives = "Retrieve Snarltooth's Head.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48535] = { id = 48535, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nazmir, the Forbidden Swamp", description = "Da Horde promised Princess Talanji dat we be dealin' with dese blood trolls in Nazmir before dey can attack Zuldazar.\n\nGrab a pterrordax and get over ta Talanji's camp in Nazmir. We be waitin' for ya there.\n\nMake sure ya ready, {name}. Dere be no civilization in Nazmir, just us and whatever be lurkin' dere.", completion = "Good, you made it. We had to move fast to avoid getting caught up in any politics.\n\nLet us proceed.", objectives = "Speak to Rokota and ride a pterrordax to Princess Talanji's camp in Nazmir.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48538] = { id = 48538, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Airtight Alibi", description = "It'll take us a while to clean up the beasts that are left over, but I'm confident we'll be able to take back Fletcher's Hollow--thanks to you, of course.\n\nHere, take this letter to the constable. It should be enough to clear Miss Waycrest's name. \n\nI'm sorry you had to witness all of this, mainlander. We are good people, but these are terrible times.", completion = "What's this? A letter from Mayor Pare?\n\n<Constable Framer reads Evelyn's letter.>\n\nWell... it appears we were... mistaken.", objectives = "Deliver Evelyn Pare's letter to Constable Henry Framer at Hangman's Point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48539] = { id = 48539, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freehold", description = "Well, there she is: Freehold.\n\nYou can get anything you want there, provided you can pay for it. \n\nWhether you pay with gold or steel is up to you.\n\nTake a look.", progress = "Look, I'm worldly, but I don't have anything you can catch from my eyes.\n\nJust use the spyglass, would ya?", completion = "Ready to head face-first into a den of snakes?", objectives = "Use Flynn's Spyglass.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48540] = { id = 48540, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aiding the Wharf", description = "We have read the tides, and never before have I seen them in such turmoil. They call to the tidesages, begging for help.\n\nA debilitating sickness is running rampant amongst the villagers, and it comes from the sea.\n\nWe are but few. There is only so much we can do!\n\nPlease, take this list and gather the listed reagents from around the pier while I attempt to calm these folks. I should be able to create a tonic that will help.\n\nI hope.", progress = "My day-to-day job usually just consists of blessing the ships, reading the waters, finding the best spots to fish�\n\nI fear that this may be out of my league.", completion = "No seaweed? This will not do at all!", objectives = "Collect a Satchel of Seaweed, a Bundle of Vellum, and some Seal Blubber from around Anglepoint Wharf.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48542] = { id = 48542, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strike Back", description = "The scroll details a dark spell which steals the souls from the neighboring Krokul to create a new demon, the Ur'zul. The scroll is signed by Lady Shahrazad.", completion = "You've been a great asset to my wranglers here. Please take this as a token of our gratitude.", objectives = "Kill 8 Eredar ritualists and Lady Shahrazad in the Petrified Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48544] = { id = 48544, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Woah, Nelly!", description = "{name}, you have my thanks. My Wranglers should be able to take it from here. If I can ask one more favor, would you pass a message to Chieftain Hatuun? Tell him the forest is secure once again. I'm sure he will reward you for all of your effort.\n\nI'll loan you one of my fastest Cragscalers for the trip. Make sure to look both ways before crossing that path outside this forest, there's a giant Legion Obliterator that patrols there. Good luck!", completion = "The Wranglers are essential for our survival here. Any assistance you have given them must be repaid.", objectives = "Return to Chieftain Hatuun in Krokul Hovel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48545] = { id = 48545, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strange Ecologies", description = "The local fauna here seem very docile and are attracted to some strange fauna on the caps above.  Why don't you try riding one?", objectives = "Use the bats to get to the top of the mushroom caps.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48546] = { id = 48546, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[48547] = { id = 48547, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quest" }
quests[48548] = { id = 48548, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quest", description = "Armed with these energized spores, you feel compelled to slam them down on the spore stalks below...", objectives = "Use your Dive ability to crush the spore stalks below you.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48549] = { id = 48549, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grozztok the Blackheart", description = "A group of us were dropped off here and left to die. \n\nOur first night at camp, I was jolted from sleep by de gurgling cries of my fellow exiles. Jakra'zet sent assassins to our camp, looking for Rakera. \n\nTheir leader, Grozztok, came for me, but Rakera intervened. \n\nShe chased him into de dunes, but dat was days ago. \n\nIf you cross paths with Grozztok, don't hesitate to drive a blade into his black heart.", completion = "You saw Jakra'zet? What would he be doing trying to break into de old pyramid?\n\nWhatever de reason, it can't be good.", objectives = "Kill Grozztok within Atul'Aman.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48550] = { id = 48550, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stolen Satchels", description = "One within our group spoke of a temple in de mountains dat welcomes exiles, though none are permitted to enter without an offering to their loa.\n\nI would have given anything to find some solace in dis wasteland, but now I have nothing, thanks to those thieving assassins.\n\nEach of us had a satchel dat carried de last of our possessions. We didn't have much, but it was more than one troll would need. \n\nIf you search de dunes looking for your friend, could you keep an eye out for our satchels?", progress = "Have you recovered our belongings?", completion = "<Jorak quickly digs through the satchels.>\n\nMuch is missing, but hopefully dere's enough here for a worthy offering.", objectives = "Collect 5 Weathered Satchels from Sandfury Assassins.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48551] = { id = 48551, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wither Without Water", description = "The flora in this area weren't always so aggressive. \n\nWithout water, the thistlevines wither and waste until they become something unrecognizable and angry.\n\nTake my watering can and wet the withering thistlevines to prevent them from becoming carnivorous.", completion = "Look how happy those plants are! You made that happen.", objectives = "Use Ranah's Watering Can to water 10 Withered Thistlevines.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48553] = { id = 48553, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Let it Flow", description = "The fountains here have seen better days. They're currently incapable of holding water, but we can fix that!\n\nYou can use my spare tools to repair the cracks. \n\nWith a little luck and elbow grease, the fountains will be flowing again in no time!", progress = "Getting the fountains working again is my top priority.", completion = "Hrm, this fountain in front of me still isn't functioning? But my work was impeccable!", objectives = "Repair the fountains within Withering Gulch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48554] = { id = 48554, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Source of the Problem", description = "I checked my work twice when working on this fountain. I made no mistakes. \n\nThere must be something wrong at the source. \n\nThe fountain draws water from a modest reservoir above the terrace. \n\nWould you mind checking it out?", progress = "There's no good reason why this fountain should be malfunctioning.", completion = "Well then, snakes! That explains it. I'm glad you cleared up that clog. The gulch looks greener already!", objectives = "Help Ranah determine the cause of the malfunctioning fountain within the Withering Terrace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48555] = { id = 48555, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We Can Salvage the Seeds", description = "I've studied the flora within the terrace extensively. Once a thistlevine completely dries out, it's too late for the plant to be saved. \n\nIts seeds are still viable, however. Under the right conditions, they can be used to cultivate new, healthy thistlevines. \n\nSalvage seeds from the carnivorous thistlevines that can no longer be saved, and plant them within the fertile mounds of dirt. \n\nThe thistlevine plant is extremely quick to sprout, so the terrace should be filled with seedlings in no time!", completion = "Look how much you've helped bring this place to life! You've got quite the green thumb.", objectives = "Plant 8 Thistlevine Seeds in Fertile Soil within the Withering Terrace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48557] = { id = 48557, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sowing Saplings", description = "Algerson destroys the forests and leaves nothing remaining! It is up to us to take care of Azeroth, to help her live and grow as she was meant to!\n\nTake these seeds, find the soil that calls for them, and help our planet recapture her grace and vitality!", completion = "Algerson's greed may have hurt this land, but it can still be saved.", objectives = "Plant seeds in 4 Loamy Soil.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48558] = { id = 48558, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Irontide Crew", description = "You see those salty looking guys in red? That's the Irontide crew.\n\nThey're the worst of the worst. Cutthroats and brigands, to a man.\n\nIrontide wouldn't be guarding the docks if they didn't stand to gain something...\n\nLighten their pockets. See what kinda hardware they've got.", progress = "What have you found?", completion = "Just as I thought - Irontide cut some kind of deal with Ashvane.\n\nFigures... birds of a feather and all that.", objectives = "Collect 3 Azerite Cutlasses and 2 Horns of Azerite Powder from Irontide Cutthroats and Irontide Trickshots.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48559] = { id = 48559, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Offering of Light", description = "I sense it. The nobility in Xe'ra's heart. Her relentless defiance of the Legion. Let this be her legacy.\n\nIn building the Vindicaar, we fashioned the Netherlight Crucible to harness the tremendous powers at play on Argus. I believe Xe'ra's essence is one key to that potential.\n\nYet the Light alone is not enough. Without balance, there can be no harmony, no cohesion.\n\nInfuse this essence into the crucible, champion. It is the first step in unlocking the strength needed to end the Burning Crusade.", completion = "An important first step, {name}.\n\nIf we can bring balance to the Netherlight Crucible, I believe it will make your weapon even more powerful.", objectives = "Infuse the Essence of Light into the Netherlight Crucible.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48560] = { id = 48560, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Offering of Shadow", description = "Can you sense it, {name}? The darkness within this essence is palpable.\n\nIn the past, I might have shunned such power, even denied its very existence. But what have we learned throughout our long struggle, if not that Light and shadow must coexist?\n\nThis may prove to be exactly what we need to bring balance to the Netherlight Crucible. To give us the edge we need against the Legion.\n\nInfuse this essence into the crucible, champion. Draw one step closer to realizing your weapon's full potential.", progress = "Light and shadow... forces that shape our very existence.", completion = "Ah, yes. Balance is key, just as the Prophet said.", objectives = "Infuse the Essence of Shadow into the Netherlight Crucible.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48561] = { id = 48561, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
