quests[48570] = { id = 48570, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[48573] = { id = 48573, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crocolisk Life", description = "I need my shaman mojo back if we are going to kill Urok. He beat me bad de last time I tried to put him down.\n\nYou help me get my power back, and I help you make Urok dead. Deal?\n\nFirst step, I need you to use dis dagger to absorb what is left of de life force of any crocolisk you kill.\n\nWhen de dagger seems full, come find me.\n\nHeh heh, dat's right Sur'jan. Dey gonna help us, den Urok will see who de strongest is!", completion = "Ah, dat looks good! Dis will make de ritual go by real nice.", objectives = "Absorb essence of 8 primal snapjaw corpses with Sur'jan's Ritual Dagger.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48574] = { id = 48574, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pulling Fangs", description = "I need more things to help me get strong. I need you to get me some saurid teeth.\n\nNo, Sur'jan, you're not trusting <him/her> TOO much. Just enough. I won't be betrayed again.\n\nI need dese teeth for a ritual I'm gonna perform to help me get my power back. Once I'm not so weak, you and I are gonna take down dis undead monster.", progress = "You got enough teeth for me?", completion = "Lemme count dem... good! Dis will work.\n\nShh, I said it will work, not dat we'd be done. Stop annoying me, Sur'jan!", objectives = "Recover 40 Saurid Teeth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48576] = { id = 48576, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Safe Flying", description = "I'm feeling... stronger! But I need more power before we take down Urok.\n\nNo, Sur'jan, YOU are scared of Urok more than me. I'm not scared of nothing!\n\nYou got an attachment to me now after dat ritual. I need you to go kill de skyterrors nearby. Their deaths will fuel my strength.\n\nTake my grappling hook. You can drag de skyterrors down from de sky with it, and it'll put de hurt on dem too.", completion = "Good! I am feeling stronger already. De three of us make a good team.", objectives = "Kill 8 Primal Skyterrors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48577] = { id = 48577, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Terrorizing their Eggs", description = "Sur'jan, I should be doing dis! What do you mean, I need to recover? Bah, fine.\n\nI need more power, and de skyterrors have eggs nearby. I need you to bash some of their eggs to fuel my energy.\n\nThose eggs got lots of life force in dem. You destroy dem, and I will feel de energy coming back to me.\n\nCome on, Sur'jan, dis will be easy! I can do dis! Hmph... well, you make a good point. You always were de smarter one out of us.", completion = "I feel better already! Maybe I should destroy more of those eggs in de future.", objectives = "Destroy 5 Skyterror eggs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48578] = { id = 48578, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "There's No Eye in Skyterror", description = "There's a real big skyterror dat I name Jarkadiax. I need his tongue...\n\nWhat's dat, Sur'jan? Not his tongue? His eye? You sure? Hrm.\n\nI need his eye for my next ritual. I know what you're thinking. De tongue makes more sense. Dat's what I--\n\nLook, Sur'jan, I still think it's his tongue. We'll see which of us is right!\n\nGo get Jarkadiax's eye and bring it back to me for de next ritual.", progress = "I need dat eye. You get it yet?", completion = "You got de eye!\n\nI feel de power coming from dis thing. Can you see it?\n\nShut up, Sur'jan. I know YOU can see it, I was talking to him!", objectives = "Recover Jarkadiax's Eye.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48579] = { id = 48579, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest", objectives = "You will learn:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48581] = { id = 48581, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Good Spanking", description = "Pinky is contained in de direhorn pen for now, but de handlers are having a real hard time with him!\n\nDis calls for some tough love.\n\nWill you help dem?", completion = "You're certainly de talk of de kraal, {name}!\n\nDat Pinky will be great in battle when he grows up, don't you think?", objectives = "Help the handlers subdue Pinky.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48584] = { id = 48584, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Blood of My Enemies", description = "I feel my power returning, but we aren't done yet. We need more power to kill dis undead Urok.\n\nWe'll be pushing in to Urok's lair. Dreadticks are swarming in de area. I want you to bring me their blood for de final ritual.\n\nTake dis. It's my trusty dreadtick gasser. Throw it in de area, dreadticks sniff it... den DIE! Hahaha! Now get going!\n\n...Sur'jan, you keep telling me to let <him/her> do dis sorta work, but I could do it too! Fine, I'll just work on getting de ritual ready.", progress = "You get me dat blood yet?", completion = "Dis will work. We are so close to getting my power back!", objectives = "Collect 45 Coagulated Dreadtick Blood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48585] = { id = 48585, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wasteland Survivor", description = "<The leather has become dry and cracked in the sun, but the supplies inside are mostly intact.\n\nIt's unknown what gruesome death befell the backpack's former owner, but supplies like these are in high demand among the outcasts.\n\nThe desert has claimed many lives... perhaps there are more supplies to be found among the dunes. >", progress = "What do you have for me?", completion = "I see you made a scavenging run and came back alive!\n\nWe will put these supplies to good use among the tribe. You have my thanks.", objectives = "Collect 10 Scavenged Supplies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48588] = { id = 48588, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Purge the Infection" }
quests[48590] = { id = 48590, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "My Head and Shoulders", description = "If we're going to fight Urok, I will need my gear back. It was all lost when I was running from Urok de first time.\n\nShut UP, Sur'jan! I had to ditch it in order to run faster.\n\nBring my gear back to me, and I'll be ready to fight Urok with you.", progress = "You got my gear?", completion = "My gear! Ah, dey smell brand new, too. Did you clean dem?", objectives = "Recover Sur'jan's head and shoulder gear.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48591] = { id = 48591, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urok's True Death", description = "This is it! My power is back; we are ready to put down Urok. He used to be a noble beast, you know. Big, strong.\n\nNow Urok is just a mindless undead. It isn't right. We'll put him to rest.\n\nI'm going to run up ahead. When you get near Urok, I'll hop out to ambush him. Let's do dis!\n\nShut up, Sur'jan. Of course we're going to win! If we don't, I'll just find another {class} to help me out.", completion = "We did it! Urok is gone for good. It was a shame to put him down, but dat sort of creature isn't supposed to be.\n\nI have lots of other things to do, like finding de two other trolls out here and killing dem.\n\nWhat do you think, Sur'jan? Should I tell him? No? Okay, fine.\n\nI'll be seeing you. Oh, and don't stay in Nazmir. Only crazy people come here.", objectives = "Defeat Urok.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48592] = { id = 48592, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Holding the Spire" }
quests[48597] = { id = 48597, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saurolisk Escape", description = "You cautiously approach a saurolisk tied to a post. It doesn't snap at you, but looks at you with defeat in its eyes.\n\nThe troggs seem to be keeping these saurolisks against their will. They should be freed before they are abused further.", completion = "Troggs training saurolisks to be ridden? Seems they've learned from watching us after all.\n\nIt's better that you freed them. I don't particularly want to imagine what would happen if the troggs were widely successful in their new riding endeavors!", objectives = "Free 6 Trapped Saurolisks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48600] = { id = 48600, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Take the Edge Off", description = "The demons streaming out of Antorus equip themselves at Felfire Armory. We need to deny those weapons. Will your {class}s fight alongside the Army of the Light once again?\n\nBefore the assault, gather materials. My smiths will craft your soldiers more powerful armor. The Legion won't give up Felfire without a fight.", progress = "Make your preparations, {name}.", completion = "One step closer to defeating the Legion.", objectives = "Raise 6 Champions to 950 Item Level.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48601] = { id = 48601, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Felfire Shattering", description = "A thin series of stone bridges connects the Burning Breach to Felfire Armory over Fiend's Run. The Army of the Light will stem Legion reinforcements while your people deal with the armory itself.\n\nWork swiftly.", completion = "There's nothing more beautiful than a lightburst charge erupting in a Legion stronghold. Your people afforded themselves well.", objectives = "Use the Scouting Map and complete the mission, \"Assault on Felfire Armory.\"", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48604] = { id = 48604, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Home Again, Home Again", description = "I can't thank you enough for the help here! You showed up just in time.\n\nHere is Elijah's sausage order. Don't worry, it's just regular sausage- nothing questionable.\n\nNow if you'll excuse me I have to see to my workers.", objectives = "Return to Elijah Eggleton in Fallhaven.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48605] = { id = 48605, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Commander's Downfall", description = "A champion of the Legion is vulnerable within an invasion point! Track it down and destroy it before it can return to fight on Argus.", progress = "The Legion must fall.", completion = "Their commanders fall before us!", objectives = "Complete a Greater Invasion Point scenario.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48606] = { id = 48606, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Loaded for Bear", description = "<This glittering cannonball stands out from the others. You notice the familiar sheen of Azerite across the surface.\n\nYou can't help but notice the nearby cannon, conveniently pointed at the ships loaded with stores of Ashvane Company weapons.>", completion = "<Better to destroy these new weapons than to let them fall into the wrong hands.>", objectives = "Use the Ashvane Cannon to destroy 6 Ashvane Co. Supplies. Azerite Cannonballs are required to fire the cannon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48613] = { id = 48613, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[48614] = { id = 48614, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Woeful Implications" }
quests[48615] = { id = 48615, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "War Never Changes" }
quests[48616] = { id = 48616, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bolas and Birds", description = "Up in the mountains we know the value of a good hunting companion. We use bolas to shoot down our flying prey, then our retrievers go and bring us our kill!\n\nYou want to take a shot? Nickel can accompany you. Shoot down some of the falcons in the woods. My dog will finish the job.", completion = "There's nothing like man and beast working together for a clean hunt!", objectives = "Shoot down 6 Hollowbeak Falcons with the Bola Launcher.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48620] = { id = 48620, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Greater Invasion Point: Mistress Alluradel" }
quests[48622] = { id = 48622, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Vanishing Lord", description = "Unfortunately, we don't have any contacts within House Waycrest, so our efforts in Drustvar will have to start from the ground up.\n\nWe have arranged for a ferry to take you to Fallhaven - a farming village in eastern Drustvar. The mayor there, Cyril White, is a longtime friend of the Proudmoores, and I think he can help us get in touch with someone from the house.\n\nI hope you can get to the bottom of their absence, {name}. Their martial might is invaluable to the Kul Tiran fleet.", completion = "<The effigy is protected by powerful magic. \n\nIt seems it will take more than brute force to break this curse.>", objectives = "Meet with Cyril White in Fallhaven in Drustvar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
